#!/bin/bash
PROJECT_NAME="secure_vault"
echo "[+] Setting up Git LFS to track large files without purging them..."

# 1. Initialize Git LFS
git lfs install

# 2. Track large file types that exceed GitHub's 50MB-100MB limit
git lfs track "*.zip"
git lfs track "*.jar"
git lfs track "*.tar.gz"
git lfs track "*.bin"
git lfs track "*.cache"
git lfs track "**/gradle-8.2-bin.zip*"
git lfs track "**/*.jar"

# 3. Stage the .gitattributes file generated by LFS
git add .gitattributes

# 4. Commit any remaining changes
git add .
git commit -m "Configure Git LFS for large binaries and prepare push" 2>/dev/null || echo "[*] Working tree ready."

# 5. Ensure remotes are correctly bound
git remote remove origin-a 2>/dev/null || true
git remote remove origin-b 2>/dev/null || true
git remote add origin-a "https://github.com/EBenterprises/secure_vault_variant_a.git"
git remote add origin-b "https://github.com/EBenterprises/secure_vault_variant_b.git"

# 6. Push LFS objects first, then code refs and tags
echo "[+] Pushing LFS objects and branches to Variant A..."
git lfs push --all origin-a
git push -u origin-a main --tags

echo "[+] Pushing LFS objects and branches to Variant B..."
git lfs push --all origin-b
git push -u origin-b main --tags

echo "[+] Complete! All files preserved via Git LFS and synchronized to GitHub."
